import ast

# Check if BankAccount class is defined
tree = ast.parse(code)

class_nodes = [node for node in ast.walk(tree) if isinstance(node, ast.ClassDef)]
class_names = [cls.name for cls in class_nodes]

if 'BankAccount' not in class_names:
    raise AssertionError('Class BankAccount is not defined')

# Find the __init__ method and check for protected attributes
for node in class_nodes:
    if node.name == 'BankAccount':
        for item in node.body:
            if isinstance(item, ast.FunctionDef) and item.name == '__init__':
                # Check that attributes are assigned with underscore prefix
                # This is a simplified check
                init_code = ast.unparse(item)
                if 'self._owner' not in init_code and 'self._balance' not in init_code:
                    raise AssertionError('__init__ should assign self._owner and self._balance')
                break
        break

