import io
import sys

# Capture output
old_stdout = sys.stdout
sys.stdout = io.StringIO()

try:
    exec_globals = {}
    exec(code, exec_globals)
    output = sys.stdout.getvalue()
finally:
    sys.stdout = old_stdout

# Check for required variables
required_vars = ['savings', 'checking']
for var in required_vars:
    if var not in exec_globals:
        raise AssertionError(f'Variable {var} not found')

# Verify they're BankAccount instances
if 'BankAccount' not in exec_globals:
    raise AssertionError('BankAccount class not found')

BankAccount = exec_globals['BankAccount']

for var in required_vars:
    if not isinstance(exec_globals[var], BankAccount):
        raise AssertionError(f'{var} should be an instance of BankAccount')

# Check initial balances
savings = exec_globals['savings']
checking = exec_globals['checking']

# Use getter methods if available, otherwise check attributes directly
if hasattr(savings, 'get_balance'):
    savings_balance = savings.get_balance()
else:
    savings_balance = savings._balance if hasattr(savings, '_balance') else None

if hasattr(checking, 'get_balance'):
    checking_balance = checking.get_balance()
else:
    checking_balance = checking._balance if hasattr(checking, '_balance') else None

# After transactions: savings 1000+200=1200, checking 500-300=200
if savings_balance != 1200:
    raise AssertionError(f'Savings balance should be 1200 after deposit, got {savings_balance}')

if checking_balance != 200:
    raise AssertionError(f'Checking balance should be 200 after withdrawal, got {checking_balance}')

# Check output
lower_output = output.lower()
if 'savings balance' not in lower_output or 'checking balance' not in lower_output:
    raise AssertionError('Output should show final balances for both accounts')

if '1200' not in output or '200' not in output:
    raise AssertionError('Output should show correct final balances (1200 and 200)')

print('TEST_PASSED')
